// ─── BUILD WORKBOOK ─────────────────────────────────────────────────────────
const wb = XLSX.utils.book_new();

// Tab 1: Master List
const masterHeaders = ['#','Tier','Church Name','Denomination','Address','City','State','ZIP','Phone','Website','Pastor','Email','Instagram','Facebook','Size','Social Activity','Best Service Fit','Outreach Status','Notes'];
const masterRows = churches.map((c, i) => [
  i+1, c.tier, c.name, c.denomination, c.address, c.city, c.state, c.zip,
  c.phone, c.website, c.pastor, c.email, c.instagram, c.facebook,
  c.size, c.social, c.fit, c.status, c.notes
]);
const masterWS = XLSX.utils.aoa_to_sheet([masterHeaders, ...masterRows]);
masterWS['!cols'] = [
  {wch:4},{wch:6},{wch:40},{wch:25},{wch:30},{wch:15},{wch:6},{wch:7},
  {wch:15},{wch:35},{wch:22},{wch:28},{wch:20},{wch:30},
  {wch:9},{wch:12},{wch:18},{wch:12},{wch:50}
];
XLSX.utils.book_append_sheet(wb, masterWS, 'Master List');

// Tab 2: Tier A Priority
const tierAChurches = churches.filter(c => c.tier === 'A');
const tierAHeaders = ['#','Church Name','Denomination','ZIP','Phone','Website','Email','Instagram','Size','Social Activity','Best Service Fit','Status','Notes'];
const tierARows = tierAChurches.map((c, i) => [
  i+1, c.name, c.denomination, c.zip, c.phone, c.website, c.email, c.instagram, c.size, c.social, c.fit, c.status, c.notes
]);
const tierAWS = XLSX.utils.aoa_to_sheet([tierAHeaders, ...tierARows]);
tierAWS['!cols'] = [{wch:4},{wch:40},{wch:25},{wch:7},{wch:15},{wch:35},{wch:28},{wch:20},{wch:9},{wch:12},{wch:18},{wch:12},{wch:50}];
XLSX.utils.book_append_sheet(wb, tierAWS, 'Tier A — Priority');

// Tab 3: Call Log
const callLogHeaders = ['Date','Church Name','Contact Name','Phone Used','Answered?','Outcome','Follow-Up Date','Notes'];
const callLogWS = XLSX.utils.aoa_to_sheet([callLogHeaders]);
callLogWS['!cols'] = [{wch:12},{wch:40},{wch:22},{wch:15},{wch:11},{wch:30},{wch:15},{wch:50}];
XLSX.utils.book_append_sheet(wb, callLogWS, 'Call Log');

// Tab 4: Call Script
const scriptHeaders = ['Script Type','Script Text'];
const scriptRows = callScripts.map(s => [s.label, s.script]);
const scriptWS = XLSX.utils.aoa_to_sheet([scriptHeaders, ...scriptRows]);
scriptWS['!cols'] = [{wch:30},{wch:120}];
XLSX.utils.book_append_sheet(wb, scriptWS, 'Call Script');

// Tab 5: Email Templates
const emailHeaders = ['Template','Subject Line','Email Body'];
const emailRows = emailTemplates.map(e => [e.label, e.subject, e.body]);
const emailWS = XLSX.utils.aoa_to_sheet([emailHeaders, ...emailRows]);
emailWS['!cols'] = [{wch:30},{wch:60},{wch:120}];
XLSX.utils.book_append_sheet(wb, emailWS, 'Email Templates');

// ─── SAVE ────────────────────────────────────────────────────────────────────
const outDir = path.join(__dirname);
const outPath = path.join(outDir, 'churches-columbia-sc.xlsx');
XLSX.writeFile(wb, outPath);

console.log(`✓ Built: ${outPath}`);
